const labels={"pv.power":"PV","grid.power":"Netz","battery.power":"Batterie","battery.soc":"SOC","buffer.temperature_upper":"Puffer","dhw.temperature":"Warmwasser","weather.outdoor_temperature":"Außen"};
function svgChart(title,unit,fields,series){const all=fields.flatMap(f=>(series[f]||[]).map(p=>p.value));if(!all.length)return `<div class="chart"><h4>${title}</h4><div class="loading">Keine Daten</div></div>`;let min=Math.min(...all),max=Math.max(...all);if(min===max){min-=1;max+=1}const W=720,H=230,P=35;const times=fields.flatMap(f=>(series[f]||[]).map(p=>Date.parse(p.time))).filter(Number.isFinite);const t0=Math.min(...times),t1=Math.max(...times);const x=t=>P+(Date.parse(t)-t0)/(t1-t0||1)*(W-2*P);const y=v=>H-P-(v-min)/(max-min)*(H-2*P);const paths=fields.map((f,i)=>{const pts=(series[f]||[]).map(p=>`${x(p.time).toFixed(1)},${y(p.value).toFixed(1)}`).join(" ");return pts?`<polyline class="line l${i}" points="${pts}"/>`:""}).join("");const legend=fields.map((f,i)=>`<span class="legend l${i}">${labels[f]||f}</span>`).join("");return `<div class="chart"><div class="chart-title"><h4>${title}</h4><span>${min.toFixed(1)}–${max.toFixed(1)} ${unit}</span></div><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" class="axis"/>${paths}</svg><div class="legend-row">${legend}</div></div>`}
async function loadHistory(id,period){const box=document.getElementById("charts");if(!box)return;box.innerHTML='<div class="loading">Lade Zeitreihen …</div>';try{const r=await fetch(`/api/v1/telemetry/history/${encodeURIComponent(id)}?period=${period}`);if(!r.ok)throw Error(r.status);const d=await r.json();box.innerHTML=chartDefs.map(([t,u,f])=>svgChart(t,u,f,d.series)).join("")}catch(e){box.innerHTML='<div class="loading">Historie konnte nicht geladen werden.</div>'}}

