function renderOekofenPlants(){const all=window._oekofenPlants||[],q=(document.getElementById("oekofenSearch")?.value||"").trim().toLowerCase();const showHidden=document.getElementById("oekofenShowHidden")?.checked||false,visible=all.filter(p=>showHidden||p.visible_in_overview!==0);const rows=q?visible.filter(p=>[p.plant_name,p.serial_number,p.version,p.customer_name,p.customer_city,...(p.problems||[]).flatMap(x=>[x.problem_type,x.message])].some(v=>String(v||"").toLowerCase().includes(q))):visible;const count=document.getElementById("oekofenSearchCount");if(count)count.textContent=q?rows.length+" Treffer":"";oekofenBoard.innerHTML=rows.map(p=>{const problemText=(p.problems||[]).map(x=>String(x.problem_type||"")+" "+String(x.message||"")).join(" ").toLowerCase(),severity=!p.problem_count?"ok":problemText.includes("warning")||problemText.includes("warnung")?"warning":"error";return `<article class="service-card oekofen-card clickable-oekofen severity-${severity}" data-plant="${esc(p.plant_id)}"><div class="device-title"><div><strong>${esc(p.plant_name||p.plant_id)}</strong><span class="service-status ${p.problem_count?"overdue":"completed"}">${p.problem_count?p.problem_count+" Störung(en)":"OK"}</span></div></div><div class="task-meta"><span>Seriennr.: ${esc(p.serial_number||"–")}</span><span>Version: ${esc(p.version||"–")}</span><span class="${p.customer_id?"":"oekofen-unassigned"}">Kunde: ${esc(p.customer_name||"NICHT ZUGEORDNET")}</span></div>${(p.problems||[]).length?`<div class="day-warning">${p.problems.map(x=>`<span>${esc(x.message||x.problem_type||"Störung")}</span>`).join("")}</div>`:""}</article>`}).join("")||'<div class="loading">Keine passenden ÖkoFEN Anlagen.</div>';document.querySelectorAll(".clickable-oekofen").forEach(card=>card.onclick=()=>openOekofenDetail(all.find(x=>String(x.plant_id)===card.dataset.plant)))}
