async function oekofenLinkForm(plantId,plant,customers){detailBody.innerHTML=`<div class="detail-head"><div><h1>ÖkoFEN zuordnen</h1><span class="meta">${esc(plant?.plant_name||plantId)} · ${esc(plant?.serial_number||"")}</span></div></div><form id="oekofenLinkForm" class="customer-form"><label>Kunde<input id="oekLinkCustomerSearch" type="search" placeholder="Name, Ort, PLZ oder Adresse suchen …" autocomplete="off"><select id="oekLinkCustomer" size="8"><option value="">– Zuordnung entfernen –</option>${customers.map(c=>`<option value="${c.id}" ${String(c.id)===String(plant?.customer_id)?"selected":""}>${esc(c.name)} · ${esc(c.postal_code||"")} ${esc(c.city||"")}</option>`).join("")}</select><small id="oekLinkCustomerMatches">${customers.length} Kunden</small></label><label>Vorhandene Anlage <small>(optional)</small><select id="oekLinkDevice"><option value="">Automatisch passende Anlage verwenden / anlegen</option></select></label><div id="oekLinkHint" class="upload-status">Kunde auswählen. INS-EI sucht anhand der Seriennummer nach einer passenden Anlage.</div><div class="form-actions"><button type="button" id="cancelOekLink" class="secondary">Abbrechen</button><button id="saveOekLink" type="submit" class="primary">Zuordnung speichern</button></div></form>`;detail.classList.remove("hidden");const customerSearch=document.getElementById("oekLinkCustomerSearch"),customerMatches=document.getElementById("oekLinkCustomerMatches"),allCustomers=customers;const renderCustomerOptions=()=>{const q=customerSearch.value.trim().toLowerCase(),current=String(oekLinkCustomer.value||plant?.customer_id||"");const filtered=allCustomers.filter(c=>!q||[c.name,c.city,c.postal_code,c.address,c.street].some(v=>String(v||"").toLowerCase().includes(q)));oekLinkCustomer.innerHTML='<option value="">– Zuordnung entfernen –</option>'+filtered.map(c=>`<option value="${c.id}" ${String(c.id)===current?"selected":""}>${esc(c.name)} · ${esc(c.postal_code||"")} ${esc(c.city||"")}</option>`).join("");customerMatches.textContent=filtered.length+" Kunden"};customerSearch.oninput=renderCustomerOptions;const loadDevices=async()=>{if(!oekLinkCustomer.value){oekLinkDevice.innerHTML='<option value="">Automatisch passende Anlage verwenden / anlegen</option>';oekLinkHint.textContent="Ohne Kunde wird die bestehende Zuordnung entfernt.";return}const r=await fetch("/api/v1/customers/"+oekLinkCustomer.value);if(!r.ok){oekLinkHint.textContent="Kundenanlagen konnten nicht geladen werden.";return}const c=await r.json(),devices=c.devices||[],serial=String(plant?.serial_number||"").toLowerCase(),match=devices.find(d=>serial&&String(d.serial_number||"").toLowerCase()===serial);oekLinkDevice.innerHTML='<option value="">Automatisch passende Anlage verwenden / anlegen</option>'+devices.map(d=>`<option value="${d.id}" ${String(d.id)===String(plant?.device_id)||(!plant?.device_id&&match&&d.id===match.id)?"selected":""}>${esc([d.manufacturer,d.model,d.serial_number].filter(Boolean).join(" · "))}</option>`).join("");const updateHint=()=>{const selected=devices.find(d=>String(d.id)===String(oekLinkDevice.value));if(selected){oekLinkHint.textContent="Diese vorhandene Anlage wird verknüpft. Hersteller, Modell und Seriennummer werden mit den ÖkoFEN-Daten abgeglichen."}else if(match){oekLinkHint.textContent="Passende Anlage über Seriennummer gefunden: "+[match.manufacturer,match.model,match.serial_number].filter(Boolean).join(" · ")}else{oekLinkHint.textContent="Keine passende Anlage ausgewählt. INS-EI legt beim Speichern automatisch eine ÖkoFEN-Anlage an."}};oekLinkDevice.onchange=updateHint;updateHint()};oekLinkCustomer.onchange=loadDevices;await loadDevices();const form=document.getElementById("oekofenLinkForm"),customerSelect=document.getElementById("oekLinkCustomer"),deviceSelect=document.getElementById("oekLinkDevice"),hint=document.getElementById("oekLinkHint"),saveButton=document.getElementById("saveOekLink"),cancelButton=document.getElementById("cancelOekLink");cancelButton.onclick=()=>detail.classList.add("hidden");form.addEventListener("submit",async e=>{e.preventDefault();saveButton.disabled=true;saveButton.textContent="Speichere …";hint.textContent="Zuordnung wird gespeichert …";const body={customer_id:customerSelect.value?Number(customerSelect.value):null,device_id:deviceSelect.value?Number(deviceSelect.value):null};try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);const r=await fetch("/api/v1/oekofen/plants/"+encodeURIComponent(plantId)+"/link",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(body),signal:controller.signal});clearTimeout(timer);const raw=await r.text();if(!r.ok)throw Error("HTTP "+r.status+" · "+raw.slice(0,220));hint.textContent="✓ Zuordnung gespeichert. ÖkoFEN-Daten wurden mit der Kundenanlage abgeglichen.";saveButton.textContent="Gespeichert";setTimeout(()=>{detail.classList.add("hidden");loadOekofen()},600)}catch(err){hint.textContent="Fehler: "+(err.name==="AbortError"?"Zeitüberschreitung beim Speichern":err.message);saveButton.disabled=false;saveButton.textContent="Zuordnung speichern";console.error("ÖkoFEN Zuordnung",err)}})}
syncOekofen.onclick=async()=>{syncOekofen.disabled=true;syncOekofen.textContent="Synchronisiere …";try{const r=await fetch("/api/v1/oekofen/sync",{method:"POST"});if(!r.ok)throw Error(r.status);await loadOekofen()}catch(e){alert("ÖkoFEN Sync fehlgeschlagen.")}syncOekofen.disabled=false;syncOekofen.textContent="Jetzt synchronisieren"};
async function loadCustomers(q=""){
  customerRows.innerHTML='<tr><td colspan="6" class="loading">Lade Kunden …</td></tr>';
  const render=d=>{
    const needle=(q||"").toLowerCase();
    let rows=d.customers||[];
    if(needle)rows=rows.filter(c=>[c.name,c.address,c.postal_code,c.city,c.phone,c.email].some(v=>String(v||"").toLowerCase().includes(needle)));
    customerCount.textContent=rows.length+" Kunden"+(d.offline?" · Offline":"");
    customerRows.innerHTML=rows.map(c=>`<tr class="customer-row" data-customer="${c.id}"><td><strong>${c.name}</strong></td><td>${c.address||"–"}</td><td>${[c.postal_code,c.city].filter(Boolean).join(" ")||"–"}</td><td>${c.phone||"–"}</td><td>${c.email||"–"}</td><td class="open">Details →</td></tr>`).join("")||'<tr><td colspan="6" class="loading">Noch keine Kunden erfasst.</td></tr>';
    document.querySelectorAll(".customer-row").forEach(x=>x.onclick=()=>openCustomer(x.dataset.customer));
  };
  try{
    const r=await fetch("/api/v1/customers"+(q?"?q="+encodeURIComponent(q):""));
    if(!r.ok)throw Error(r.status);
    const d=await r.json();render(d);
    if(window.INSOffline)await INSOffline.putMany("customers",d.customers||[]);
  }catch(e){
    try{
      const cached=window.INSOffline?await INSOffline.getAll("customers"):[];
      if(cached.length){render({customers:cached,offline:true});return}
    }catch(_){}
    customerRows.innerHTML='<tr><td colspan="6" class="loading">Kunden konnten nicht geladen werden.</td></tr>';
  }
}
let customerTimer;customerSearch.oninput=()=>{clearTimeout(customerTimer);customerTimer=setTimeout(()=>loadCustomers(customerSearch.value.trim()),200)};
