function openPhoto(url,name){detailBody.insertAdjacentHTML("beforeend",`<div id="photoViewer" class="photo-viewer"><button type="button" class="close photo-close">×</button><img src="${url}" alt="${esc(name)}"><span>${esc(name)}</span></div>`);document.querySelector(".photo-close").onclick=()=>photoViewer.remove();photoViewer.onclick=e=>{if(e.target===photoViewer)photoViewer.remove()}}
function bindPhotos(){document.querySelectorAll(".photo-thumb").forEach(b=>b.onclick=()=>openPhoto(b.dataset.photo,b.dataset.name))}
function visitCard(v){const photos=(window._customerFiles||[]).filter(f=>String(f.visit_id)===String(v.id));return `<div class="device-card"><div class="device-title"><strong>${v.visit_date} · ${v.title}</strong><button class="secondary edit-visit" data-visit="${v.id}">Bearbeiten</button></div>${v.description?`<span>${v.description}</span>`:""}<span>${v.duration_hours??"–"} h · ${v.travel_km??"–"} km${v.invoice_reference?" · "+v.invoice_reference:""}</span>${photos.length?`<div class="photo-grid">${photos.map(fileThumb).join("")}</div>`:""}</div>`}
function editVisitForm(customer,v){detailBody.innerHTML=`<div class="detail-head"><div><h1>Einsatz bearbeiten</h1><span class="meta">${customer.name}</span></div></div><form id="visitEditForm" class="customer-form"><label>Datum<input name="visit_date" type="date" required value="${esc(v.visit_date)}"></label><label>Titel<input name="title" required value="${esc(v.title)}"></label><label>Beschreibung<textarea name="description" rows="5">${esc(v.description)}</textarea></label><div class="form-row"><label>Arbeitszeit (h)<input name="duration_hours" type="number" step="0.25" min="0" value="${v.duration_hours??""}"></label><label>Fahrt (km)<input name="travel_km" type="number" step="1" min="0" value="${v.travel_km??""}"></label></div><label>Material<textarea name="material" rows="3">${esc(v.material)}</textarea></label><label>Rechnung / Beleg<input name="invoice_reference" value="${esc(v.invoice_reference)}"></label><label>Weitere Fotos<input id="editVisitPhotos" type="file" accept="image/*" capture="environment" multiple></label><div class="form-actions"><button type="button" class="secondary" id="cancelVisitEdit">Abbrechen</button><button type="submit" class="primary">Änderungen speichern</button></div></form>`;cancelVisitEdit.onclick=()=>openCustomer(customer.id);visitEditForm.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(visitEditForm).entries());delete data.editVisitPhotos;["duration_hours","travel_km"].forEach(k=>{if(data[k]==="")delete data[k];else data[k]=Number(data[k])});const r=await fetch("/api/v1/customers/"+customer.id+"/visits/"+v.id,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(r.ok){for(const file of editVisitPhotos.files){const fd=new FormData();fd.append("file",file);fd.append("visit_id",v.id);await fetch("/api/v1/customers/"+customer.id+"/files",{method:"POST",body:fd})}openCustomer(customer.id)}else alert("Einsatz konnte nicht gespeichert werden.")}}
