function deviceMaintenanceForm(customer,d){detailBody.innerHTML=`<div class="detail-head"><div><h1>Wartungseinstellungen</h1><span class="meta">${esc(d.manufacturer||"")} ${esc(d.model||"")}</span></div></div><form id="deviceMaintenanceForm" class="customer-form"><label>Wartungsintervall<select name="maintenance_interval_months"><option value="12">Jährlich (12 Monate)</option><option value="24">Alle 2 Jahre (24 Monate)</option><option value="6">6 Monate</option><option value="36">36 Monate</option></select></label><label>Nächste Fälligkeit<input name="maintenance_next_due_date" type="date" value="${d.maintenance_next_due_date||""}"></label><div class="form-actions"><button type="button" class="secondary" id="cancelDeviceMaintenance">Abbrechen</button><button type="submit" class="primary">Speichern</button></div></form>`;const maintenanceSettingsForm=document.getElementById("deviceMaintenanceForm");maintenanceSettingsForm.elements.maintenance_interval_months.value=String(d.maintenance_interval_months||12);document.getElementById("cancelDeviceMaintenance").onclick=()=>openCustomer(customer.id);maintenanceSettingsForm.addEventListener("submit",async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(maintenanceSettingsForm).entries());data.maintenance_interval_months=Number(data.maintenance_interval_months);if(!data.maintenance_next_due_date)data.maintenance_next_due_date=null;const r=await fetch("/api/v1/devices/"+d.id+"/maintenance-settings",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(r.ok)openCustomer(customer.id);else alert("Wartungseinstellungen konnten nicht gespeichert werden.");});}
