async function linkDeviceForm(customer,deviceId){const r=await fetch("/api/v1/devices/"+deviceId+"/link-options");if(!r.ok)return;const d=await r.json(),dev=d.device;const serial=(dev.serial_number||"").toLowerCase(),touch=(dev.touch_id||"").toLowerCase();const score=p=>{const s=(p.serial_number||"").toLowerCase(),n=(p.plant_name||"").toLowerCase();return (serial&&s.includes(serial)?10:0)+(touch&&(n.includes(touch)||s.includes(touch))?10:0)};const plants=[...d.oekofen].sort((a,b)=>score(b)-score(a));detailBody.innerHTML=`<div class="detail-head"><div><h1>Anlage verknüpfen</h1><span class="meta">${dev.manufacturer||""} ${dev.model||""}</span></div></div><form id="linkForm" class="customer-form"><label>ÖkoFEN Onlineanlage<input id="oekofenSearch" type="search" placeholder="Name, Kesselnummer oder Touch-ID suchen …"><select id="oekofenSelect" name="oekofen_plant_id" size="8"><option value="">– nicht verknüpft –</option>${plants.map(p=>`<option value="${esc(p.plant_id)}" ${p.plant_id===dev.oekofen_plant_id?"selected":""}>${esc(p.plant_name||p.plant_id)} · ${esc(p.serial_number||"")}${score(p)?" · Treffer":""}</option>`).join("")}</select><small id="oekofenMatches">${plants.length} Anlagen</small></label><label>INS-EI Instanz<select name="ins_installation_id"><option value="">– nicht verknüpft –</option>${d.ins_ei.map(i=>`<option value="${esc(i.installation_id)}" ${i.installation_id===dev.ins_installation_id?"selected":""}>${esc(i.installation_id)}</option>`).join("")}</select></label><div class="form-actions"><button type="button" class="secondary" id="cancelLinks">Abbrechen</button><button type="submit" class="primary">Verknüpfung speichern</button></div></form>`;const allPlants=plants;oekofenSearch.oninput=()=>{const q=oekofenSearch.value.trim().toLowerCase();const filtered=allPlants.filter(p=>!q||[p.plant_name,p.serial_number,p.plant_id].some(v=>String(v||"").toLowerCase().includes(q)));oekofenSelect.innerHTML='<option value="">– nicht verknüpft –</option>'+filtered.map(p=>`<option value="${esc(p.plant_id)}" ${p.plant_id===dev.oekofen_plant_id?"selected":""}>${esc(p.plant_name||p.plant_id)} · ${esc(p.serial_number||"")}${score(p)?" · Treffer":""}</option>`).join("");oekofenMatches.textContent=filtered.length+" Anlagen"};cancelLinks.onclick=()=>openCustomer(customer.id);linkForm.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(linkForm).entries());const x=await fetch("/api/v1/devices/"+deviceId+"/links",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(x.ok)openCustomer(customer.id);else alert("Verknüpfung konnte nicht gespeichert werden.")}}
function deviceFilesForm(customer,d){const files=(window._customerFiles||[]).filter(f=>String(f.device_id)===String(d.id));detailBody.innerHTML=`<div class="detail-head"><div><h1>Fotos / Dokumente</h1><span class="meta">${esc(customer.name)} · ${esc([d.manufacturer,d.model].filter(Boolean).join(" "))}</span></div></div><section class="group"><div class="history-head"><h3>Anlagendateien</h3><span class="meta">${files.length} Dateien</span></div><div class="documents-grid">${files.length?files.map(fileThumb).join(""):'<div class="loading">Noch keine Fotos oder Dokumente.</div>'}</div></section><form id="deviceFileForm" class="customer-form"><label>Foto / Dokument<input id="deviceFileInput" type="file" accept="image/*,.pdf,.doc,.docx,.xls,.xlsx" multiple required><small>Am Handy kannst du Fotos direkt aufnehmen oder vorhandene Dateien auswählen.</small></label><label>Beschreibung<input id="deviceFileDescription" placeholder="optional"></label><div id="deviceFileStatus" class="upload-status">Bereit</div><div class="form-actions"><button type="button" class="secondary" id="cancelDeviceFiles">Zurück</button><button type="submit" class="primary">Hochladen</button></div></form>`;detail.classList.remove("hidden");bindPhotos();cancelDeviceFiles.onclick=()=>openCustomer(customer.id);deviceFileForm.onsubmit=async e=>{e.preventDefault();const selected=[...deviceFileInput.files];if(!selected.length)return;const button=deviceFileForm.querySelector('button[type="submit"]');button.disabled=true;button.textContent="Lade hoch …";let ok=0;for(const file of selected){const fd=new FormData();fd.append("file",file);fd.append("device_id",d.id);fd.append("description",deviceFileDescription.value);try{const r=await fetch("/api/v1/customers/"+customer.id+"/files",{method:"POST",body:fd});if(!r.ok)throw Error(r.status);ok++}catch(err){if(window.INSOffline){await INSOffline.queueFile(customer.id,file,{device_id:d.id,description:deviceFileDescription.value});ok++}}}deviceFileStatus.textContent=ok+" von "+selected.length+" Datei(en) gespeichert"+(navigator.onLine?"":" · Offline-Sync ausstehend");if(ok===selected.length)setTimeout(()=>openCustomer(customer.id),600);else{button.disabled=false;button.textContent="Hochladen"}}}
