    document.getElementById("applyCustomerImport").onclick=async()=>{if(!confirm(d.new+" neue Kunden anlegen und "+d.matches+" vorhandene Kunden ergänzen?"))return;const x=await fetch("/api/v1/customers/import-apply",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({rows:window._customerImportRows,apply:true})});if(x.ok){const result=await x.json();alert(result.created+" Kunden angelegt, "+result.updated+" ergänzt.");detail.classList.add("hidden");loadCustomers()}};
