let activeTaskStatus="today",taskFilters={project:"",customer:"",priority:""};
function taskDueState(t){
  if(t.status==="completed")return "completed";if(!t.due_at)return "none";
  const due=new Date(t.due_at),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),tomorrow=new Date(today);tomorrow.setDate(tomorrow.getDate()+1);
  if(due<today)return "overdue";if(due<tomorrow)return "today";return "upcoming";
}
function taskPriorityLabel(p){return p==="urgent"?"Dringend":p==="high"?"Hoch":p==="low"?"Niedrig":"Normal"}
function taskSortKey(t){
  const due=taskDueState(t),dueRank={overdue:0,today:1,upcoming:2,none:3,completed:4}[due]??3,priority={urgent:0,high:1,normal:2,low:3}[t.priority]??2;
  return [dueRank,t.due_at||"9999",priority,t.title||""];
}
function compareTasks(a,b){const x=taskSortKey(a),y=taskSortKey(b);for(let i=0;i<x.length;i++){if(x[i]<y[i])return -1;if(x[i]>y[i])return 1}return 0}
async function loadTasks(status=activeTaskStatus){
  activeTaskStatus=status;
  const r=await fetch("/api/v1/tasks?t="+Date.now(),{cache:"no-store"});if(!r.ok)return;
  const all=(await r.json()).tasks||[];
  const open=all.filter(t=>t.status!=="completed"),counts={overdue:0,today:0,upcoming:0,none:0,in_progress:0,completed:0};
  all.forEach(t=>{const ds=taskDueState(t);if(counts[ds]!==undefined)counts[ds]++;if(t.status==="in_progress")counts.in_progress++;if(t.status==="completed")counts.completed++});
  taskSummary.innerHTML=`<button class="task-stat today" data-summary="today"><b>${counts.overdue+counts.today}</b><span>Heute</span></button><button class="task-stat" data-summary="planned"><b>${counts.upcoming}</b><span>Geplant</span></button><button class="task-stat" data-summary="all"><b>${open.length}</b><span>Alle offen</span></button><button class="task-stat" data-summary="none"><b>${counts.none}</b><span>Ohne Termin</span></button><button class="task-stat" data-summary="completed"><b>${counts.completed}</b><span>Erledigt</span></button>`;
  document.querySelectorAll("[data-summary]").forEach(b=>b.onclick=()=>{activeTaskStatus=b.dataset.summary;document.querySelectorAll(".task-filters button").forEach(x=>x.classList.toggle("selected",x.dataset.taskFilter===activeTaskStatus));loadTasks(activeTaskStatus)});
  const projects=[...new Map(all.filter(t=>t.project_id||t.project_name).map(t=>[String(t.project_id||t.project_name),{id:String(t.project_id||t.project_name),name:t.project_name||("Projekt #"+t.project_id)}])).values()].sort((a,b)=>a.name.localeCompare(b.name,"de"));
  const customers=[...new Map(all.filter(t=>t.customer_id).map(t=>[String(t.customer_id),{id:String(t.customer_id),name:t.customer_name||("Kunde #"+t.customer_id)}])).values()].sort((a,b)=>a.name.localeCompare(b.name,"de"));
  const pf=document.getElementById("taskProjectFilter"),cf=document.getElementById("taskCustomerFilter");
  const pv=taskFilters.project,cv=taskFilters.customer;pf.innerHTML='<option value="">Alle Projekte</option>'+projects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("");cf.innerHTML='<option value="">Alle Kunden</option>'+customers.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("");pf.value=pv;cf.value=cv;
  let tasks=all;
  if(status==="completed")tasks=tasks.filter(t=>t.status==="completed");else if(status==="today")tasks=tasks.filter(t=>t.status!=="completed"&&["overdue","today"].includes(taskDueState(t)));else if(status==="planned")tasks=tasks.filter(t=>t.status!=="completed"&&taskDueState(t)==="upcoming");else if(status==="none")tasks=tasks.filter(t=>t.status!=="completed"&&taskDueState(t)==="none");else tasks=tasks.filter(t=>t.status!=="completed");
  if(taskFilters.project)tasks=tasks.filter(t=>String(t.project_id||t.project_name)===taskFilters.project);
  if(taskFilters.customer)tasks=tasks.filter(t=>String(t.customer_id)===taskFilters.customer);
  if(taskFilters.priority)tasks=tasks.filter(t=>t.priority===taskFilters.priority);
  tasks.sort(compareTasks);window._tasks=tasks;taskCount.textContent=tasks.length+" Aufgaben";
  taskBoard.innerHTML=tasks.map(t=>{const due=taskDueState(t),project=t.project_name||(t.project_id?"Projekt #"+t.project_id:"Allgemein");return `<article class="service-card task-card priority-${t.priority} due-${due}"><div class="task-card-top"><div><strong class="task-title">${esc(t.title)}</strong><div class="task-badges"><span class="priority-badge ${t.priority}">${taskPriorityLabel(t.priority)}</span>${due==="overdue"?`<span class="due-badge overdue">${Math.max(1,Math.floor((new Date(new Date().getFullYear(),new Date().getMonth(),new Date().getDate())-new Date(t.due_at))/86400000))} Tag(e) überfällig</span>`:due==="today"?'<span class="due-badge today">Heute</span>':t.status==="in_progress"?'<span class="service-status in_progress">In Arbeit</span>':""}</div></div><div class="task-card-actions"><button class="secondary edit-task" data-id="${t.id}">Öffnen</button>${t.customer_address?`<a class="secondary navigate-task" href="https://maps.apple.com/?daddr=${encodeURIComponent([t.customer_address,t.customer_postal_code,t.customer_city,t.customer_country].filter(Boolean).join(", "))}" target="_blank" rel="noopener">↗ Navigieren</a>`:""}${t.status!=="completed"?`<button class="primary complete-task" data-id="${t.id}">✓ Erledigt</button>`:""}</div></div>${t.description?`<p>${esc(t.description)}</p>`:""}<div class="task-meta"><span>📁 ${esc(project)}</span>${t.customer_name?`<span>👤 ${esc(t.customer_name)}</span>`:""}${t.due_at?`<span>📅 ${new Date(t.due_at).toLocaleString("de-AT")}</span>`:'<span>📅 Ohne Termin</span>'}${t.remind_at?`<span>🔔 ${new Date(t.remind_at).toLocaleString("de-AT")}</span>`:""}</div></article>`}).join("")||'<div class="task-empty">Keine Aufgaben in dieser Ansicht.</div>';
  document.querySelectorAll(".edit-task").forEach(b=>b.onclick=()=>taskForm(window._tasks.find(t=>String(t.id)===b.dataset.id)));
  document.querySelectorAll(".complete-task").forEach(b=>b.onclick=async()=>{
    const task=window._tasks.find(t=>String(t.id)===b.dataset.id);if(!task)return;
    b.disabled=true;b.textContent="Erledige …";
    const data={title:task.title,description:task.description,status:"completed",priority:task.priority,due_at:task.due_at,category:task.category,project_name:task.project_name,project_id:task.project_id,customer_id:task.customer_id,remind_at:task.remind_at};
    try{const r=await fetch("/api/v1/tasks/"+task.id,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(!r.ok)throw Error(r.status);await loadTasks(activeTaskStatus)}catch(e){b.disabled=false;b.textContent="✓ Erledigt";alert("Aufgabe konnte nicht erledigt werden.")}
  });
}
document.querySelectorAll(".task-filters button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".task-filters button").forEach(x=>x.classList.toggle("selected",x===b));loadTasks(b.dataset.taskFilter)});
