async function taskForm(task=null,projectContext=null){
  const [cr,pr]=await Promise.all([fetch("/api/v1/customers"),fetch("/api/v1/projects")]);
  const customers=cr.ok?(await cr.json()).customers:[],projects=pr.ok?(await pr.json()).projects:[];
  const fixedProject=projectContext||null;
  detailBody.innerHTML=`<div class="detail-head"><div><h1>${task?"Aufgabe bearbeiten":"Aufgabe anlegen"}</h1>${fixedProject?`<span class="meta">${esc(fixedProject.name)} · ${esc(fixedProject.customer_name||"Intern")}</span>`:""}</div></div>
  <form id="taskEditor" class="customer-form">
    <label>Titel<input name="title" required value="${esc(task?.title)}"></label>
    <label>Beschreibung<textarea name="description" rows="4">${esc(task?.description)}</textarea></label>
    <div class="form-row"><label>Status<select name="status"><option value="open">Offen</option><option value="in_progress">In Arbeit</option><option value="completed">Erledigt</option></select></label><label>Priorität<select name="priority"><option value="low">Niedrig</option><option value="normal">Normal</option><option value="high">Hoch</option><option value="urgent">Dringend</option></select></label></div>
    ${fixedProject?`<input type="hidden" name="project_id" value="${fixedProject.id}"><input type="hidden" name="customer_id" value="${fixedProject.customer_id||""}">`:`<label>Projekt<select name="project_id"><option value="">– kein Projekt –</option>${projects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></label><label>Kunde${customerPicker(customers,"customer_id",task?.customer_id||"")}</label>`}
    <label>Kategorie<input name="category" value="${esc(task?.category)}"></label>
    <div class="form-row"><label>Fällig<input name="due_at" type="datetime-local" value="${esc((task?.due_at||"").slice(0,16))}"></label><label>🔔 Erinnern am<input name="remind_at" type="datetime-local" value="${esc((task?.remind_at||"").slice(0,16))}"><button type="button" id="copyDueToReminder" class="secondary copy-date-button">Fälligkeit als Erinnerung übernehmen</button></label></div><div class="appointment-box"><label class="appointment-toggle"><input id="taskHasAppointment" type="checkbox" ${task?.scheduled_start?"checked":""}> Als Termin planen</label><div id="taskAppointmentFields" class="form-row ${task?.scheduled_start?"":"hidden"}"><label>Beginn<input name="scheduled_start" type="datetime-local" value="${esc((task?.scheduled_start||"").slice(0,16))}"></label><label>Ende<input name="scheduled_end" type="datetime-local" value="${esc((task?.scheduled_end||"").slice(0,16))}"></label></div></div>
    <div id="taskSaveStatus" class="upload-status">Bereit</div>
    <div class="form-actions"><button type="button" class="secondary" id="taskCancel">Abbrechen</button><button type="submit" class="primary" id="taskSave">Speichern</button></div>
  </form>`;
  const form=document.getElementById("taskEditor"),save=document.getElementById("taskSave"),status=document.getElementById("taskSaveStatus");
  form.elements.status.value=task?.status||"open";form.elements.priority.value=task?.priority||"normal";
  if(!fixedProject){form.elements.project_id.value=task?.project_id||"";form.elements.customer_id.value=task?.customer_id||""}
  detail.classList.remove("hidden");bindCustomerPickers(detailBody);document.getElementById("taskCancel").onclick=()=>fixedProject?openProject(fixedProject.id):detail.classList.add("hidden");document.getElementById("copyDueToReminder").onclick=()=>{const due=form.elements.due_at.value;if(!due){status.textContent="Bitte zuerst eine Fälligkeit wählen.";return}form.elements.remind_at.value=due;status.textContent="Fälligkeit als Erinnerung übernommen."};const appointmentToggle=document.getElementById("taskHasAppointment"),appointmentFields=document.getElementById("taskAppointmentFields");appointmentToggle.onchange=()=>appointmentFields.classList.toggle("hidden",!appointmentToggle.checked);
  form.addEventListener("submit",async event=>{
    event.preventDefault();save.disabled=true;save.textContent="Speichere …";status.textContent="Speichere Aufgabe …";
    const fd=new FormData(form),data={
      title:String(fd.get("title")||"").trim(),description:String(fd.get("description")||"")||null,
      status:String(fd.get("status")||"open"),priority:String(fd.get("priority")||"normal"),
      project_id:fd.get("project_id")?Number(fd.get("project_id")):null,customer_id:fd.get("customer_id")?Number(fd.get("customer_id")):null,
      category:String(fd.get("category")||"")||null,project_name:null,due_at:fd.get("due_at")||null,remind_at:fd.get("remind_at")||null,scheduled_start:appointmentToggle.checked?(fd.get("scheduled_start")||null):null,scheduled_end:appointmentToggle.checked?(fd.get("scheduled_end")||null):null,outlook_event_id:task?.outlook_event_id||null
    };
    if(!data.title){status.textContent="Titel fehlt.";save.disabled=false;save.textContent="Speichern";return}if(data.scheduled_start&&!data.scheduled_end){status.textContent="Für einen Termin fehlt das Ende.";save.disabled=false;save.textContent="Speichern";return}if(data.scheduled_start&&data.scheduled_end&&new Date(data.scheduled_end)<=new Date(data.scheduled_start)){status.textContent="Terminende muss nach dem Beginn liegen.";save.disabled=false;save.textContent="Speichern";return}
    const url=task?"/api/v1/tasks/"+task.id:"/api/v1/tasks";
    try{
      const response=await fetch(url,{method:task?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});
      const body=await response.json().catch(()=>({}));
      if(!response.ok)throw Error(typeof body.detail==="string"?body.detail:"HTTP "+response.status);
      const id=body.id||task?.id;
      status.textContent="Aufgabe #"+id+" gespeichert.";
      if(fixedProject){
        const check=await fetch("/api/v1/projects/"+fixedProject.id+"?t="+Date.now(),{cache:"no-store"});
        if(!check.ok)throw Error("Projekt konnte nach dem Speichern nicht geprüft werden");
        const fresh=await check.json();
        if(!(fresh.tasks||[]).some(x=>Number(x.id)===Number(id)))throw Error("Aufgabe gespeichert, Projektverknüpfung fehlt");
        await openProject(fixedProject.id);
      }else{detail.classList.add("hidden");await loadTasks()}
    }catch(err){status.textContent="Fehler: "+err.message;save.disabled=false;save.textContent="Speichern"}
  });
}
newTask.onclick=()=>taskForm();
async function routeFromHash(){
  const hash=location.hash.slice(1),parts=hash.split("/");
  const view=["customers","instances","visits","maintenances","tasks","projects","oekofen"].includes(parts[0])?parts[0]:"dashboard";
  setView(view);
  if(parts[0]==="tasks"&&parts[1]==="task"&&parts[2]){
    try{const r=await fetch("/api/v1/tasks?t="+Date.now(),{cache:"no-store"});if(r.ok){const d=await r.json(),task=(d.tasks||[]).find(x=>String(x.id)===parts[2]);if(task)await taskForm(task)}}catch(e){}
  }
}
routeFromHash();
window.addEventListener("hashchange",routeFromHash);
if("serviceWorker" in navigator){
  navigator.serviceWorker.addEventListener("message",event=>{
    if(event.data?.type!=="INS_EI_NAVIGATE"||!event.data.hash)return;
    const hash=String(event.data.hash);
    if(location.hash===hash)routeFromHash();else location.hash=hash;
  });
}

